using System.Security.Cryptography;

namespace AngularCrudApi.Auth;

/// <summary>Bound from the "Security" configuration section.</summary>
public sealed class SecurityOptions
{
    public const string SectionName = "Security";

    /// <summary>Consecutive failed sign-ins before the account is locked.</summary>
    public int MaxFailedLoginAttempts { get; set; } = 5;

    public int LockoutMinutes { get; set; } = 15;

    /// <summary>Length of passwords generated by an administrator's reset or account creation.</summary>
    public int TemporaryPasswordLength { get; set; } = 14;

    /// <summary>
    /// How long the per-request stamp/session check may use a cached answer. Changes made through this
    /// API evict the cache at once; the TTL only matters for changes made directly in the database or by
    /// another API instance.
    /// </summary>
    public int ValidationCacheSeconds { get; set; } = 30;
}

/// <summary>Password rules shared by signup, change-password and generated passwords.</summary>
public static class PasswordPolicy
{
    public const int MinLength = 8;
    public const string StrengthMessage = "Include an uppercase letter, a lowercase letter and a digit";

    public static bool IsStrong(string password) =>
        password.Length >= MinLength &&
        password.Any(char.IsUpper) && password.Any(char.IsLower) && password.Any(char.IsDigit);

    /// <summary>Random password that always satisfies <see cref="IsStrong"/> (no look-alike characters).</summary>
    public static string GenerateTemporary(int length)
    {
        const string upper = "ABCDEFGHJKLMNPQRSTUVWXYZ";
        const string lower = "abcdefghijkmnpqrstuvwxyz";
        const string digits = "23456789";
        const string all = upper + lower + digits;
        length = Math.Max(length, 12);

        var chars = new char[length];
        chars[0] = upper[RandomNumberGenerator.GetInt32(upper.Length)];
        chars[1] = lower[RandomNumberGenerator.GetInt32(lower.Length)];
        chars[2] = digits[RandomNumberGenerator.GetInt32(digits.Length)];
        for (var i = 3; i < length; i++) chars[i] = all[RandomNumberGenerator.GetInt32(all.Length)];
        RandomNumberGenerator.Shuffle(chars.AsSpan());
        return new string(chars);
    }
}
